document.addEventListener('click', function(ev){
  var el = ev.target.closest && ev.target.closest('.thcard.cardtip, #themeScatter g.pt');
  if (!el || tipHostOf(ev.target)) return;
  var inner = ev.target.closest('.info-btn, a[href], button, .ckt, .caticon, .cardi');
  if (inner && inner !== el && el.contains(inner)) return;
  if (popoverOwner === el) { closePopover(); return; }
  /* ET-29257: a hovering device already shows the card, so one click opens the detail */
  if (hoverDevice() && ev.pointerType !== 'touch' && ev.pointerType !== 'pen') return;
  ev.stopPropagation(); ev.preventDefault();
  pinHost(el);
}, true)

